import numpy as np
L=np.log(eps); LT=np.log(T)
Fe={'1':np.ones_like(eps),'L':L,'e':eps,'1/e':1/eps,'e2':eps**2,'eL':eps*L}
Ft={'1':np.ones_like(T),'T':T,'T2':T**2,'T3':T**3,'lT':LT,'1/T':1/T}
cols=[];names=[]
for a in Fe:
    for b in Ft:
        cols.append(Fe[a]*Ft[b]); names.append(a+'*'+b)
A=np.column_stack(cols)
c,_,_,_=np.linalg.lstsq(A,sigma,rcond=None)
r=sigma-A@c
print('nmse',np.mean(r**2)/np.var(sigma), A.shape)
# greedy backward elimination
keep=list(range(A.shape[1]))
while len(keep)>1:
    best=None
    for k in keep:
        kk=[j for j in keep if j!=k]
        cc,_,_,_=np.linalg.lstsq(A[:,kk],sigma,rcond=None)
        rr=sigma-A[:,kk]@cc
        e=np.mean(rr**2)/np.var(sigma)
        if best is None or e<best[0]: best=(e,k)
    keep.remove(best[1])
    if len(keep)<=14 or best[0]>1e-6:
        pass
    if best[0]>1e-6 and len(keep)<14: 
        keep.append(best[1]); break
    print(len(keep), best[0], names[best[1]] )
print([names[k] for k in keep])

